CSS='\n:root{--body-background-fill:#f4f6fa;--body-text-color:#20283d;--block-background-fill:white;--input-background-fill:#f8f9fc;--border-color-primary:#e6eaf2;--block-border-width:0px;--block-label-background-fill:transparent;--block-title-text-color:#47516b}\nbody{background:#f4f6fa!important}.gradio-container{width:100%!important;max-width:1560px!important;margin:0 auto!important;padding:0!important;font-family:"Microsoft YaHei UI",Arial,sans-serif!important}.gradio-container main.fillable{max-width:none!important;width:100%!important;padding:0!important}\n#app-shell{gap:0!important;min-height:100vh;align-items:stretch}#sidebar{background:#15213a!important;min-width:216px!important;max-width:240px!important;padding:30px 20px!important;border-radius:0!important;gap:28px!important;min-height:100vh}\n.brand{display:flex;gap:12px;align-items:center;color:white}.brand-mark{width:38px;height:38px;background:#829cff;border-radius:12px;display:grid;place-items:center;font-size:23px;font-weight:800}.brand strong{font-size:19px;letter-spacing:1px}.brand small{display:block;color:#9daac3;font-size:10px;letter-spacing:2px;margin-top:4px}\n.nav-label{font-size:10px;color:#8997b1;letter-spacing:2px;margin:20px 0 12px}.sidebar-copy{font-size:12px;line-height:1.9;color:#a4b0c8}.sidebar-tag{border:1px solid #34415b;padding:10px 12px;border-radius:10px;color:#b9c9ff;font-size:11px}.nav-radio{background:transparent!important;border:0!important}.nav-radio>div{display:flex!important;flex-direction:column!important;gap:8px!important}.nav-radio label{background:transparent!important;border:0!important;color:#bcc7dc!important;border-radius:10px!important;padding:14px 12px!important;box-shadow:none!important;cursor:pointer}.nav-radio label.selected{background:#2b3c61!important;color:white!important}.nav-radio input{display:none!important}.nav-radio label span{font-size:14px!important}\n#workspace{padding:30px 38px 44px!important;gap:24px!important;min-width:0!important}#topbar{display:flex;justify-content:space-between;align-items:center;padding-bottom:19px;border-bottom:1px solid #dfe5ef}.eyebrow{color:#7b88a3;font-size:10px;letter-spacing:2px;font-weight:600}.app-title{font-size:26px;color:#202c45;font-weight:700;line-height:1.4;margin-top:6px}.online-badge{background:#e8f6ef;color:#307958;font-size:11px;padding:8px 13px;border-radius:30px;white-space:nowrap}.intro{color:#77829a;font-size:13px;margin:8px 0 0;line-height:1.7}\n.mode-head{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:0 0 3px}.mode-head h2{font-size:21px;color:#27334d;margin:0 0 7px;font-weight:700}.mode-head p{font-size:12px;color:#7e89a0;margin:0;line-height:1.8}.model-badge{border:1px solid #d7dff4;background:#edf1ff;color:#536bb9;padding:10px 14px;border-radius:10px;font-size:12px;white-space:nowrap}\n.panel,#draw-settings,#draw-results,#formal-script,#formal-settings,#formal-segments,#formal-results,#library-saved,#library-import,#models-panel{background:#fff!important;border:1px solid #e5e9f2!important;border-radius:16px!important;padding:22px!important;box-shadow:0 3px 12px #22335b03!important;gap:16px!important}.panel-title{display:flex;align-items:center;gap:10px;color:#2d3952;font-size:14px;font-weight:700;margin-bottom:2px}.step{width:23px;height:23px;display:inline-grid;place-items:center;background:#edf1fc;color:#6a7fc0;border-radius:7px;font-size:11px}.panel-sub{color:#8a94aa;font-size:11px;margin-top:7px;line-height:1.7}.quiet{color:#8a94a8;font-size:11px;line-height:1.8;margin:0}.surface-row{gap:22px!important;align-items:stretch!important}.section-gap{gap:20px!important}.gradio-container textarea,.gradio-container input{font-size:13px!important;color:#34405a!important;border-radius:10px!important}.gradio-container textarea{line-height:1.85!important}.gradio-container label>span{font-size:12px!important;color:#6a7590!important}.gradio-container button.primary{background:#5774de!important;border:1px solid #5774de!important;box-shadow:0 4px 10px #5774de24!important;color:white!important;min-height:44px;border-radius:10px!important;font-weight:600!important}.gradio-container button.secondary{border-radius:10px!important;background:#fff!important;border:1px solid #e0e5ee!important;color:#58657f!important;box-shadow:none!important;min-height:39px}.gradio-container button.stop{background:#fff7f7!important;color:#a65d64!important;border:1px solid #f0dfe1!important;box-shadow:none!important;border-radius:10px!important;min-height:39px}\n#sidebar .form{background:transparent!important;border:0!important}#sidebar .nav-radio label span{color:#bbc8e0!important}#sidebar .nav-radio label.selected span{color:white!important}.brand strong{color:#fff!important}#sidebar .status-box{background:transparent!important}#sidebar .status-box textarea{background:#202f4b!important;color:#b4c2dd!important}\n.audio-panel{background:#f7f9fd!important;border-radius:12px!important;min-height:138px!important;border:1px solid #e9edf4!important}.status-box textarea{font-size:12px!important;background:#f3f6fd!important;color:#657391!important}.gradio-container .tabs{border:0!important}.gradio-container .tab-nav{border-bottom:1px solid #e6eaf1!important;gap:18px!important}.gradio-container .tab-nav button{border:0!important;padding:12px 0!important;font-size:12px!important;color:#8a94aa!important}.gradio-container .tab-nav button.selected{color:#536ed2!important;border-bottom:2px solid #617bde!important}.gradio-container .tabitem{padding:16px 0 0!important;border:0!important}.engine-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.engine{background:#f8f9fd;border:1px solid #e7ebf4;border-radius:12px;padding:16px}.engine b{font-size:13px;color:#43516d}.engine small{display:block;color:#8b95aa;font-size:11px;margin-top:7px;line-height:1.7}.engine-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#70aa91;margin-right:8px}.model-upcoming{padding:14px 16px;border:1px dashed #dfe4ee;border-radius:12px;color:#7d89a1;font-size:12px;line-height:1.9}.count-label{color:#8c97ac;font-size:11px;text-align:right;margin-top:0px}.gradio-container footer{display:none!important}.compact-note{color:#8d97ab;font-size:11px;line-height:1.8;padding:8px 0}.gradio-container .block{box-shadow:none!important}\n@media(max-width:950px){#sidebar{min-width:165px!important;max-width:180px!important;padding:23px 14px!important}#workspace{padding:24px 20px!important}.mode-head{align-items:flex-start;flex-direction:column;gap:10px}.surface-row{flex-wrap:wrap!important}.engine-grid{grid-template-columns:1fr}}\n@media(max-width:650px){#app-shell{flex-direction:column!important}#sidebar{max-width:100%!important;min-height:auto!important;padding:18px!important;gap:12px!important}.nav-radio>div{flex-direction:row!important}.sidebar-copy,.sidebar-tag,.nav-label{display:none!important}#workspace{padding:20px 14px!important}.panel{padding:16px!important}#topbar .online-badge{display:none}.app-title{font-size:22px}}\n'